<template><div class="ui-banner" :class="`ui-banner--${tone}`" role="status"><Icon :name="icon" size="sm"/><div><strong v-if="title">{{ title }}</strong><slot>{{ message }}</slot></div><UiIconButton v-if="dismissible" label="关闭" variant="ghost" density="mini" @click="emit('dismiss')"><Icon name="x" size="xs"/></UiIconButton></div></template>
<script setup lang="ts">import{computed}from'vue';import Icon from'@/components/icons/Icon.vue';import UiIconButton from'./UiIconButton.vue';const props=withDefaults(defineProps<{tone?:'info'|'success'|'warning'|'danger';title?:string;message?:string;dismissible?:boolean}>(),{tone:'info'});const emit=defineEmits<{dismiss:[]}>();const icon=computed<'checkCircle'|'exclamationTriangle'|'exclamationCircle'|'infoCircle'>(()=>props.tone==='success'?'checkCircle':props.tone==='warning'?'exclamationTriangle':props.tone==='danger'?'exclamationCircle':'infoCircle');</script>
<style scoped>.ui-banner{display:grid;grid-template-columns:16px 1fr auto;align-items:center;gap:9px;min-height:40px;padding:7px 12px;border-block:1px solid color-mix(in srgb,var(--ui-info) 20%,var(--ui-border));color:var(--ui-info);background:color-mix(in srgb,var(--ui-info) 5%,var(--ui-surface))}.ui-banner>div{color:var(--ui-text-muted);line-height:20px}.ui-banner strong{margin-right:6px;color:var(--ui-text)}.ui-banner--success{color:var(--ui-success)}.ui-banner--warning{color:var(--ui-warning)}.ui-banner--danger{color:var(--ui-danger)}</style>
